pub fn has_only_one_distinct_element(a: &[i32]) -> bool {
    // If the slice is empty or has one element, by definition it has only one distinct value.
    // Otherwise, compare every element to the first one.
    if let Some(&first) = a.first() {
        a.iter().skip(1).all(|&x| x == first)
    } else {
        true
    }
}

